@Composable
fun AncApp(ancViewModel: AncViewModel = viewModel()) {
  val navController = rememberNavController()
  val patients by ancViewModel.patients.collectAsState()
  val patientDetails by ancViewModel.patientDetails.collectAsState()
  val questionnaireJson by ancViewModel.questionnaireJson.collectAsState()
  val syncState by ancViewModel.syncState.collectAsState()

  NavHost(
    navController = navController,
    startDestination = "register",
  ) {
    composable("register") {
      RegisterScreen(
        patients = patients,
        syncState = syncState,
        onSyncClick = { ancViewModel.syncNow() },
        onPatientClick = { patientId ->
          navController.navigate("patient/$patientId")
        },
      )
    }

    composable(
      route = "patient/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
    ) { backStackEntry ->
      val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
      val detailState = patientDetails[patientId]
      PatientDetailScreen(
        patient = detailState?.patient ?: patients.firstOrNull { it.id == patientId },
        visits = detailState?.visits.orEmpty(),
        onBackClick = { navController.popBackStack() },
        onRecordVisitClick = {
          navController.navigate("newVisit/$patientId")
        },
      )
    }

    composable(
      route = "newVisit/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
    ) { backStackEntry ->
      val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
      val patientName =
        patientDetails[patientId]?.patient?.name
          ?: patients.firstOrNull { it.id == patientId }?.name
          ?: "Patient"
      NewVisitScreen(
        patientName = patientName,
        questionnaireJson = questionnaireJson,
        onSaveVisit = { response, onDone ->
          ancViewModel.saveVisit(patientId, response, onDone)
        },
        onCancel = { navController.popBackStack() },
      )
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientSummary>,
  syncState: String?,
  onSyncClick: () -> Unit,
  onPatientClick: (String) -> Unit,
) {
  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              text = "ANC Register",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            if (!syncState.isNullOrBlank()) {
              Text(
                text = syncState,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
              )
            }
          }
        },
        actions = {
          OutlinedButton(
            onClick = onSyncClick,
            modifier = Modifier.padding(end = 8.dp),
          ) {
            Text("Sync")
          }
        },
        colors =
          TopAppBarDefaults.topAppBarColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant,
          ),
      )
    }
  ) { innerPadding ->
    if (patients.isEmpty()) {
      Box(
        modifier = Modifier.fillMaxSize().padding(innerPadding).padding(24.dp),
        contentAlignment = Alignment.Center,
      ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
          Text(
            text = syncState ?: "Loading patients from FHIR server…",
            style = MaterialTheme.typography.bodyLarge,
          )
          Spacer(modifier = Modifier.height(12.dp))
          Button(onClick = onSyncClick) {
            Text("Retry Sync")
          }
        }
      }
    } else {
      LazyColumn(
        modifier = Modifier.fillMaxSize().padding(innerPadding),
        contentPadding = PaddingValues(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
      ) {
        items(patients, key = { it.id }) { patient ->
          Card(
            modifier =
              Modifier.fillMaxWidth().clickable {
                onPatientClick(patient.id)
              },
            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
          ) {
            Column(modifier = Modifier.padding(16.dp)) {
              Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
              ) {
                Text(
                  text = patient.name,
                  style = MaterialTheme.typography.titleMedium,
                  fontWeight = FontWeight.Bold,
                )
                Text(
                  text =
                    patient.currentWeeksPregnant?.let { "$it weeks pregnant" }
                      ?: "Weeks unknown",
                  style = MaterialTheme.typography.labelLarge,
                  color = MaterialTheme.colorScheme.primary,
                  fontWeight = FontWeight.SemiBold,
                )
              }
              Spacer(modifier = Modifier.height(8.dp))
              Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
              ) {
                Text(
                  text =
                    buildString {
                      append("Age: ")
                      append(patient.ageYears?.let { "$it yrs" } ?: "N/A")
                      patient.birthDate?.let { append(" (DOB: $it)") }
                    },
                  style = MaterialTheme.typography.bodyMedium,
                )
              }
              Spacer(modifier = Modifier.height(4.dp))
              Text(
                text = "Est. due date: ${patient.dueDate?.toString() ?: "Not recorded"}",
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Medium,
              )
            }
          }
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientDetailScreen(
  patient: PatientSummary?,
  visits: List<AncVisitItem>,
  onBackClick: () -> Unit,
  onRecordVisitClick: () -> Unit,
) {
  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Text(
            text = patient?.name ?: "Patient Details",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold,
          )
        },
        navigationIcon = {
          TextButton(onClick = onBackClick) {
            Text("Back")
          }
        },
        colors =
          TopAppBarDefaults.topAppBarColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant,
          ),
      )
    },
  ) { innerPadding ->
    LazyColumn(
      modifier = Modifier.fillMaxSize().padding(innerPadding),
      contentPadding = PaddingValues(16.dp),
      verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
      item {
        Card(
          modifier = Modifier.fillMaxWidth(),
          colors =
            CardDefaults.cardColors(
              containerColor = MaterialTheme.colorScheme.secondaryContainer,
            ),
        ) {
          Column(modifier = Modifier.padding(16.dp)) {
            Text(
              text = patient?.name ?: "Unknown Patient",
              style = MaterialTheme.typography.titleMedium,
              fontWeight = FontWeight.Bold,
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
              text =
                "Age: ${patient?.ageYears?.let { "$it yrs" } ?: "N/A"}" +
                  (patient?.birthDate?.let { " • DOB: $it" } ?: ""),
              style = MaterialTheme.typography.bodyMedium,
            )
            Text(
              text =
                "Est. Due Date: ${patient?.dueDate?.toString() ?: "N/A"}" +
                  (patient?.currentWeeksPregnant?.let { " • $it weeks pregnant" } ?: ""),
              style = MaterialTheme.typography.bodyMedium,
              fontWeight = FontWeight.Medium,
            )
            Spacer(modifier = Modifier.height(12.dp))
            Button(
              onClick = onRecordVisitClick,
              modifier = Modifier.fillMaxWidth(),
            ) {
              Text("Record New ANC Visit")
            }
          }
        }
      }

      item {
        Spacer(modifier = Modifier.height(4.dp))
        Text(
          text = "Past ANC Visits (${visits.size})",
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Bold,
        )
      }

      if (visits.isEmpty()) {
        item {
          Text(
            text = "No ANC visits recorded yet.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
          )
        }
      } else {
        items(visits, key = { it.id }) { visit ->
          Card(
            modifier = Modifier.fillMaxWidth(),
            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
          ) {
            Column(modifier = Modifier.padding(16.dp)) {
              Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
              ) {
                Text(
                  text = "Visit Date: ${visit.dateText}",
                  style = MaterialTheme.typography.titleSmall,
                  fontWeight = FontWeight.Bold,
                )
                if (visit.gestationalAgeWeeks != null) {
                  Text(
                    text = "${visit.gestationalAgeWeeks} weeks",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.primary,
                  )
                }
              }
              HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
              VisitDetailRow(label = "Weight", value = visit.weightText ?: "Not recorded")
              VisitDetailRow(label = "Blood Pressure", value = visit.bpText ?: "Not recorded")
              if (visit.hbText != null) {
                VisitDetailRow(label = "Hemoglobin", value = visit.hbText)
              }
              if (!visit.dangerSignsText.isNullOrBlank()) {
                VisitDetailRow(label = "Danger Signs", value = visit.dangerSignsText)
              }
              if (!visit.notesText.isNullOrBlank()) {
                VisitDetailRow(label = "Notes", value = visit.notesText)
              }
            }
          }
        }
      }
    }
  }
}

@Composable
private fun VisitDetailRow(label: String, value: String) {
  Row(
    modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp),
    horizontalArrangement = Arrangement.SpaceBetween,
  ) {
    Text(
      text = "$label:",
      style = MaterialTheme.typography.bodyMedium,
      color = MaterialTheme.colorScheme.onSurfaceVariant,
    )
    Text(
      text = value,
      style = MaterialTheme.typography.bodyMedium,
      fontWeight = FontWeight.Medium,
    )
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewVisitScreen(
  patientName: String,
  questionnaireJson: String,
  onSaveVisit: (dev.ohs.fhir.model.r4.QuestionnaireResponse, () -> Unit) -> Unit,
  onCancel: () -> Unit,
) {
  val scope = rememberCoroutineScope()

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              text = "Record ANC Visit",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            Text(
              text = patientName,
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
          }
        },
        navigationIcon = {
          TextButton(onClick = onCancel) {
            Text("Cancel")
          }
        },
        colors =
          TopAppBarDefaults.topAppBarColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant,
          ),
      )
    }
  ) { innerPadding ->
    Box(
      modifier = Modifier.fillMaxSize().padding(innerPadding),
    ) {
      Questionnaire(
        questionnaireJson = questionnaireJson,
        onSubmit = { getResponse ->
          scope.launch {
            try {
              val response = getResponse()
              onSaveVisit(response) {
                onCancel()
              }
            } catch (_: CancellationException) {
              // Validation failed; Questionnaire composable displays validation errors in-place.
            }
          }
        },
        onCancel = onCancel,
      )
    }
  }
}
